H.background();
const v = H.plot2d({ xMin: -5, xMax: 5, yMin: -5, yMax: 5 });
v.grid(); v.axes();
const a = P.a, b = P.b;
const circle = [], curve = [];
const N = 360;
for (let i = 0; i <= N; i++) {
  const th = i / N * H.TAU;
  const r1 = a;
  const r2 = b * (1 + Math.cos(th));
  circle.push([r1 * Math.cos(th), r1 * Math.sin(th)]);
  curve.push([r2 * Math.cos(th), r2 * Math.sin(th)]);
}
v.path(circle, { color: H.colors.accent, width: 2.5 });
v.path(curve, { color: H.colors.accent2, width: 2.5 });
let count = 0;
const c = a / Math.max(1e-6, b) - 1;
if (c >= -1 && c <= 1) {
  const th0 = Math.acos(c);
  [th0, -th0].forEach(th => {
    v.dot(a * Math.cos(th), a * Math.sin(th), { r: 6 + Math.sin(t * 3), fill: H.colors.warn });
    count++;
  });
}
const ph = (t * 0.5) % H.TAU;
v.line(0, 0, a * Math.cos(ph), a * Math.sin(ph), { color: H.colors.good, width: 1.5, dash: [4, 4] });
